/** ⟦Guarda en memoria. Para una base de datos cambia SÓLO esta clase (la misma interfaz).¦Stores in memory. For a database change ONLY this class (the same interface).⟧ */
export class Repositorio {
  private filas = new Map<number, Registro>();
  private siguiente = 1;

  listar(): Registro[] {
    return [...this.filas.values()];
  }
  obtener(id: number): Registro | undefined {
    return this.filas.get(id);
  }
  crear(v: Entrada): Registro {
    const r = { id: this.siguiente++, ...v };
    this.filas.set(r.id, r);
    return r;
  }
  cambiar(id: number, v: Entrada): Registro | undefined {
    if (!this.filas.has(id)) return undefined;
    const r = { id, ...v };
    this.filas.set(id, r);
    return r;
  }
  borrar(id: number): boolean {
    return this.filas.delete(id);
  }
}
